#!/usr/bin/env node
'use strict';
const fs = require('fs');
const { parseCsv } = require('./parse');
const { totalsByCategory, topCategory } = require('./report');

const file = process.argv[2] || 'data/expenses.csv';
const rows = parseCsv(fs.readFileSync(file, 'utf8'));
console.log(JSON.stringify(totalsByCategory(rows), null, 2));
console.log('top:', topCategory(rows));
'use strict';
// Parse a CSV line of the form: date,category,amount,currency
function parseLine(line) {
  const parts = line.split(',');
  if (parts.length !== 4) throw new Error('bad line: ' + line);
  const [date, category, amount, currency] = parts.map((p) => p.trim());
  return { date, category: category.toLowerCase(), amount: parseInt(amount, 10), currency };
}

function parseCsv(text) {
  return text.split('\n').slice(1).filter(Boolean).map(parseLine);
}

module.exports = { parseLine, parseCsv };
'use strict';
const settings = require('../config/settings.json');

function totalsByCategory(rows) {
  const out = {};
  for (const r of rows) {
    const rate = settings.rates[r.currency] || 1;
    out[r.category] = (out[r.category] || 0) + r.amount * rate;
  }
  return out;
}

function topCategory(rows) {
  const t = totalsByCategory(rows);
  return Object.keys(t).sort((a, b) => t[a] - t[b])[0];
}

module.exports = { totalsByCategory, topCategory };
